"use client";

import { useState, FormEvent } from "react";
import "./login.css";

/* ── base64 assets (embedded so there are no external image deps) ── */
const LOGO_SRC = "data:image/png;base64,";
const CAMPUS_BG = "data:image/jpeg;base64,";

export default function LoginPage() {
  const [userId, setUserId] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [redirecting, setRedirecting] = useState(false);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError("");

    if (!userId.trim()) {
      setError("Enter your matric number or email.");
      return;
    }
    if (!password) {
      setError("Enter your password.");
      return;
    }

    setSubmitting(true);

    // TODO: replace with real auth call
    setTimeout(() => {
      setSubmitting(false);
      setRedirecting(true);
    }, 1500);
  };

  const buttonLabel = redirecting
    ? "Redirecting\u2026"
    : submitting
    ? "Signing in\u2026"
    : "Sign in";

  return (
    <div
      className="loginBody"
      style={{ "--campus-bg": `url('${CAMPUS_BG}')` } as React.CSSProperties}
    >
      <div className="loginPage">
        {/* Logo */}
        <div className="logoWrap">
          <img
            src={LOGO_SRC}
            alt="Lagos State University of Science and Technology"
          />
        </div>

        <div className="uniName">
          Lagos State University of Science and Technology
        </div>
        <div className="appTitle">Computer Based Test System</div>

        {/* Error banner */}
        {error && (
          <div className={`banner bannerVisible`}>
            <svg viewBox="0 0 24 24">
              <circle cx="12" cy="12" r="10" />
              <line x1="15" y1="9" x2="9" y2="15" />
              <line x1="9" y1="9" x2="15" y2="15" />
            </svg>
            <span>{error}</span>
          </div>
        )}

        {/* Form */}
        <form className="loginForm" onSubmit={handleSubmit} noValidate>
          <div className="field">
            <label htmlFor="userId">Matric number or staff email</label>
            <div className="inputWrap">
              <input
                type="text"
                id="userId"
                className="mono"
                placeholder="e.g. CSC/2022/305"
                autoComplete="username"
                autoFocus
                value={userId}
                onChange={(e) => setUserId(e.target.value)}
              />
            </div>
          </div>

          <div className="field">
            <label htmlFor="password">Password</label>
            <div className="inputWrap">
              <input
                type={showPw ? "text" : "password"}
                id="password"
                placeholder="Enter your password"
                autoComplete="current-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <button
                type="button"
                className="togglePw"
                aria-label={showPw ? "Hide password" : "Show password"}
                aria-pressed={showPw}
                onClick={() => setShowPw(!showPw)}
              >
                <svg viewBox="0 0 24 24">
                  {showPw ? (
                    <>
                      <path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24" />
                      <line x1="1" y1="1" x2="23" y2="23" />
                    </>
                  ) : (
                    <>
                      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                      <circle cx="12" cy="12" r="3" />
                    </>
                  )}
                </svg>
              </button>
            </div>
          </div>

          <label className="keepSigned">
            <input type="checkbox" />
            Keep me signed in on this device
          </label>

          <button
            type="submit"
            className="btnPrimary"
            disabled={submitting || redirecting}
          >
            {submitting && <span className="spinner" />}
            <span>{buttonLabel}</span>
          </button>

          <a href="#" className="forgotLink">
            Forgot password?
          </a>
        </form>

        <div className="loginFooter">
          <a href="#">Need help? Contact ICT</a>
          <a href="#">Terms</a>
          <a href="#">Privacy (NDPA)</a>
        </div>
      </div>
    </div>
  );
}
